/* SPDX-License-Identifier: GPL-3.0-only */
/*
 * Chicago AU Env ADSR → filter EG dual-drive.
 *
 * Chicago Acid AU 3.1.6 exposes one Env Attack/Decay/Sustain/Release. native303
 * splits amp ADSR (AAtt..ARel) from the TeeBee filter EG (FAttack/Decay/
 * FSustain/FRelease + FEnv). Leaving filter Decay at the Open303 default (64)
 * with FEnv=303 makes Gate-mode factory presets (amp held open) ignore Env
 * Attack/Sustain — the audible envelope is then only the wrong filter sweep.
 *
 * AU compare and factory decode mirror Env into both amp ADSR and filter ADSR
 * (FEnv = ADSR). Product UI pages stay independent; this helper only runs when
 * applying AU/factory Env bytes.
 */
#ifndef CHICAGO_ENV_H
#define CHICAGO_ENV_H

#include <stdint.h>
#include "../dsp/bass303.h"

/* AU/factory 0..255 → 0..max_pot (matches chicago_au_map._pot_from_byte). */
static inline uint8_t chi_env_pot_from_byte(uint8_t v, uint8_t max_pot)
{
    if (max_pot == 0)
        return 0;
    return (uint8_t)(((uint32_t)v * (uint32_t)max_pot + 127u) / 255u);
}

/*
 * After amp ADSR pots (AAtt/ADec/ASus/ARel) are set from AU Env bytes, mirror
 * them onto the filter EG and select FEnv ADSR mode.
 */
static inline void chi_env_mirror_amp_to_filter(uint8_t *voice_pots)
{
    if (!voice_pots)
        return;
    voice_pots[BASS303_FATTACK] = voice_pots[BASS303_AATTACK];
    voice_pots[BASS303_DECAY] = voice_pots[BASS303_ADECAY];
    voice_pots[BASS303_FSUSTAIN] = voice_pots[BASS303_ASUSTAIN];
    voice_pots[BASS303_FRELEASE] = voice_pots[BASS303_ARELEASE];
    voice_pots[BASS303_FENV] = 1; /* ADSR */
}

/* Apply AU Env Attack/Decay/Sustain/Release bytes (factory pots[7..10]) to amp
 * ADSR and mirrored filter EG on a 303 voice cell. */
static inline void chi_env_apply_factory_voice(uint8_t *voice_pots, const uint8_t env_bytes[4])
{
    if (!voice_pots || !env_bytes)
        return;
    voice_pots[BASS303_AATTACK] = chi_env_pot_from_byte(env_bytes[0], 127);
    voice_pots[BASS303_ADECAY] = chi_env_pot_from_byte(env_bytes[1], 127);
    voice_pots[BASS303_ASUSTAIN] = chi_env_pot_from_byte(env_bytes[2], 127);
    voice_pots[BASS303_ARELEASE] = chi_env_pot_from_byte(env_bytes[3], 127);
    chi_env_mirror_amp_to_filter(voice_pots);
}

#endif /* CHICAGO_ENV_H */

/* SPDX-License-Identifier: GPL-3.0-only */
/* Seeded two-bank live-event property test, compiled against production breaks.c.
 * Legacy and optimized BREAK decoders must emit bit-identical PCM under the same
 * press/release/tempo/pitch/bank-replacement/retrigger sequence. */
#include <inttypes.h>
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "firmware/src/dsp/breaks.h"

#define BLOCK 64
#define LIVE_BLOCKS 160
#define QUIET_BLOCKS 16
#define LENGTHS 7
#define SEEDS 4

static uint32_t rnd(uint32_t *state)
{
    uint32_t x = *state;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return *state = x;
}

static void demand(int yes, const char *what)
{
    if (!yes) {
        fprintf(stderr, "FAIL: %s\n", what);
        exit(1);
    }
}

static FILE *pcm;
static uint64_t pressed, released, banks_replaced, reversed, tempo_changes;

static void emit(breaks_t *b, uint64_t *audible)
{
    struct {
        uint32_t before;
        float data[BLOCK];
        uint32_t after;
    } guarded;
    guarded.before = UINT32_C(0x4e4f5445);
    guarded.after = UINT32_C(0x4f464621);
    for (unsigned i = 0; i < BLOCK; i++)
        guarded.data[i] = NAN;
    breaks_render(b, guarded.data, BLOCK);
    demand(guarded.before == UINT32_C(0x4e4f5445) &&
           guarded.after == UINT32_C(0x4f464621), "renderer overran output buffer");
    for (unsigned i = 0; i < BLOCK; i++) {
        demand(isfinite(guarded.data[i]) && fabsf(guarded.data[i]) <= 2.f,
               "non-finite or unbounded audio sample");
        if (guarded.data[i] != 0.f)
            ++*audible;
    }
    demand(fwrite(guarded.data, sizeof(float), BLOCK, pcm) == BLOCK, "write PCM");
}

static void run_one(uint32_t n, uint32_t seedno)
{
    uint32_t state = UINT32_C(0x7331ad57) ^ n ^ (seedno * UINT32_C(0x9e3779b9));
    uint8_t *raw_a = malloc(((size_t)n + 1u) / 2u);
    uint8_t *raw_b = malloc(((size_t)n + 1u) / 2u);
    breaks_t *b = calloc(1u, sizeof(*b));
    demand(raw_a && raw_b && b, "test allocation");
    for (uint32_t i = 0; i < (n + 1u) / 2u; i++) {
        raw_a[i] = (uint8_t)rnd(&state);
        raw_b[i] = (uint8_t)rnd(&state);
    }
    unsigned bars = (seedno & 1u) ? 1u : 2u;
    brk_loop_t a = {.adpcm = raw_a, .nsamples = n, .rate = 22050, .bars = bars};
    brk_loop_t c = {.adpcm = raw_b, .nsamples = n, .rate = 22050, .bars = bars};
    breaks_init(b);
    breaks_set_loop(b, 0, &a);
    breaks_set_loop(b, 1, &c);
    demand(b->bank[0].valid && b->bank[1].valid, "generated banks valid");
    breaks_set(b, BRK_LEVEL, 127);
    breaks_set(b, BRK_COMPLEX, 100);
    breaks_set(b, BRK_BCHANCE, 100);
    breaks_set(b, BRK_ROLL, 67);
    breaks_set(b, BRK_R2, 80);
    breaks_set(b, BRK_R4, 100);
    breaks_set(b, BRK_ALEN, 0);
    breaks_set(b, BRK_BLEN, 0);
    const float rates[] = {31.875f, 32.125f, 64.875f, 257.125f};
    float samples16 = ((float)n / ((float)bars * 16.f)) / rates[seedno & 3u];
    uint16_t held = 0;
    uint64_t audible = 0;
    breaks_live(b, 8, 1);
    held |= UINT16_C(1) << 8;
    breaks_step(b, 0, 0, samples16, 1);
    for (unsigned block = 0; block < LIVE_BLOCKS; block++) {
        uint32_t action = rnd(&state);
        if (block % 2u == 0u) {
            unsigned key = (action >> 17) % 8u;
            uint16_t bit = (uint16_t)(UINT16_C(1) << key);
            int down = !(held & bit);
            breaks_live(b, (int)key, down);
            held = down ? (uint16_t)(held | bit) : (uint16_t)(held & ~bit);
            if (down) pressed++; else released++;
        }
        if (block % 5u == 0u) {
            unsigned key = 8u + (action % 3u);
            uint16_t bit = (uint16_t)(UINT16_C(1) << key);
            int down = !(held & bit);
            breaks_live(b, (int)key, down);
            held = down ? (uint16_t)(held | bit) : (uint16_t)(held & ~bit);
            if (key == 8u) reversed++;
        }
        if (block % 7u == 0u)
            breaks_set(b, BRK_PITCH, (int)((action >> 9) % 25u));
        if (block % 13u == 0u) {
            /* Different bank generation, overlapping release and new slice. */
            unsigned which = (action >> 10) & 1u;
            breaks_set_loop(b, (int)which, which ? &c : &a);
            banks_replaced++;
        }
        if (block % 9u == 0u)
            breaks_pin(b, (int)((action >> 4) % 8u));
        if (block % 11u == 0u) {
            /* Exact same clock/BPM data for both compiler branches. */
            float factor = (action & 1u) ? 1.125f : 0.875f;
            samples16 *= factor;
            samples16 = fmaxf(2.f, fminf(samples16, 1000000.f));
            tempo_changes++;
        }
        if (block % 4u == 0u)
            breaks_step(b, (int)((block / 4u) & 15u), (int)(block / 64u),
                        samples16, (block % 12u) != 0u);
        emit(b, &audible);
    }
    /* No held-key NoteOff leaks, even after rapid overlapping key changes. */
    for (int key = 0; key <= 10; key++)
        breaks_live(b, key, 0);
    breaks_stop(b);
    breaks_set_quiet(b, 1);
    for (unsigned block = 0; block < QUIET_BLOCKS; block++) {
        emit(b, &audible);
        if (block == QUIET_BLOCKS - 1)
            demand(breaks_silent(b), "silence/drain after NoteOff and STOP");
    }
    demand(audible != 0, "test must have audible signal before STOP");
    printf("n=%" PRIu32 " seed=%" PRIu32 " audible=%" PRIu64 " silent=1\n", n, seedno, audible);
    free(b);
    free(raw_a);
    free(raw_b);
}

int main(int argc, char **argv)
{
    if (argc != 2) {
        fputs("usage: property-test /path/to/pcm\n", stderr);
        return 2;
    }
    pcm = fopen(argv[1], "wb");
    if (!pcm) { perror("open PCM"); return 3; }
    static const uint32_t lengths[LENGTHS] = {65u, 511u, 512u, 513u, 4097u, 176400u, 2116800u};
    for (unsigned n = 0; n < LENGTHS; n++)
        for (unsigned seedno = 0; seedno < SEEDS; seedno++)
            run_one(lengths[n], seedno);
    demand(pressed > 0 && released > 0 && banks_replaced > 0 && reversed > 0 && tempo_changes > 0,
           "live event types must actually occur");
    printf("events: pressed=%" PRIu64 " released=%" PRIu64 " bank_replace=%" PRIu64
           " reverse=%" PRIu64 " tempo=%" PRIu64 "\n",
           pressed, released, banks_replaced, reversed, tempo_changes);
    if (fclose(pcm)) { perror("close PCM"); return 3; }
    return 0;
}

#!/usr/bin/env python3
"""Native clock/transport order regression using functions extracted from sequencer.c.

This is a scoped source-function test, not a complete firmware target build.
When multiple MIDI packets arrive in one audio block, clocks before an accepted
Start/Continue/PLAY belong to the previous transport epoch; clocks after it
belong to the new one. A rejected PLAY echo must not discard its preceding ticks.
"""
import argparse
import os
import pathlib
import re
import subprocess
import sys
import tempfile

FUNCTIONS = (
    "request_start", "request_continue", "seq_start", "seq_stop",
    "seq_continue", "seq_ext_clock", "seq_midi_rt",
)


def function_body(src, name):
    pattern = r"(?:static )?(?:void|int)\s+" + name + r"\s*\([^;]*\)\s*(?:/\*.*?\*/\s*)?\{"
    match = re.search(pattern, src, re.S)
    if not match:
        raise ValueError("missing production function: " + name)
    pos = src.index("{", match.start())
    depth = 0
    for idx in range(pos, len(src)):
        if src[idx] == "{":
            depth += 1
        elif src[idx] == "}":
            depth -= 1
            if depth == 0:
                return src[match.start():idx + 1]
    raise ValueError("unterminated production function: " + name)


def apply_block(src):
    begin = src.index("if (s->req_stop) {")
    end = re.search(r"s->midi_req\s*=\s*0\s*;[^\n]*", src[begin:])
    if not end:
        raise ValueError("missing production transport application block")
    return src[begin:begin + end.end()]


PREFIX = r'''
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#define SEQ_CLK_INT 1u
#define TRK_DRUM 0
#define FS 44100u

typedef struct {
    uint8_t req_start, req_cont, req_stop, req_rt, req_stop_rt, midi_req;
    uint8_t clk_src, playing, start_local;
    uint32_t ext_pending, ext_now, start_at, req_prior_ticks;
    uint32_t starts, continues, stops;
} seq_t;
typedef struct { int unused; } seq_sink_t;
static uint32_t seq_step_q8(const seq_t *s, int rate)
{ (void)s; (void)rate; return 11025u * 256u; }
static int part_rate(const seq_t *s, int track)
{ (void)s; (void)track; return 0; }
static void do_start(seq_t *s, int top, const seq_sink_t *o, uint8_t remote)
{ (void)top; (void)o; (void)remote; (void)o; s->playing = 1; if (top) s->starts++; else s->continues++; }
static void do_stop(seq_t *s, const seq_sink_t *o, uint8_t remote)
{ (void)o; (void)remote; (void)o; s->playing = 0; s->stops++; }
'''
SUFFIX = r'''
static void apply_transport(seq_t *s)
{
    seq_sink_t sink = {0};
    const seq_sink_t *o = &sink;
    TRANSPORT_APPLY
}
static unsigned checks = 0, failures = 0;
#define CHECK(expr, text) do { checks++; if (!(expr)) { failures++; fprintf(stderr, "FAIL %s\n", text); } } while (0)
int main(void)
{
    seq_t s = {0};
    for (int i = 0; i < 6; i++) seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFA); apply_transport(&s);
    CHECK(s.ext_pending == 0, "F8 packets before remote Start cannot belong to new transport");
    CHECK(s.starts == 1, "Start still starts playback");

    memset(&s, 0, sizeof s);
    seq_midi_rt(&s, 0xFA); seq_midi_rt(&s, 0xF8); apply_transport(&s);
    CHECK(s.ext_pending == 1, "F8 after remote Start must survive");

    memset(&s, 0, sizeof s);
    for (int i = 0; i < 6; i++) seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFA);
    seq_midi_rt(&s, 0xF8); seq_midi_rt(&s, 0xF8); apply_transport(&s);
    CHECK(s.ext_pending == 2, "mixed packet ordering preserves only post-Start F8");

    memset(&s, 0, sizeof s);
    for (int i = 0; i < 6; i++) seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFB); apply_transport(&s);
    CHECK(s.ext_pending == 0, "F8 before remote Continue cannot advance resumed phase");

    memset(&s, 0, sizeof s);
    for (int i = 0; i < 6; i++) seq_midi_rt(&s, 0xF8);
    seq_start(&s); apply_transport(&s);
    CHECK(s.ext_pending == 0, "F8 before local PLAY cannot advance new phase");
    CHECK(s.start_local == 1, "local PLAY provenance is preserved");

    memset(&s, 0, sizeof s);
    seq_start(&s); apply_transport(&s);
    seq_midi_rt(&s, 0xF8); seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFA); apply_transport(&s);
    CHECK(s.ext_pending == 2, "ignored remote PLAY echo MUST preserve queued F8");
    CHECK(s.starts == 1, "ignored PLAY echo cannot restart step one");

    memset(&s, 0, sizeof s);
    seq_midi_rt(&s, 0xF8); seq_midi_rt(&s, 0xFA);
    seq_midi_rt(&s, 0xF8); seq_midi_rt(&s, 0xFB);
    seq_midi_rt(&s, 0xF8); apply_transport(&s);
    CHECK(s.ext_pending == 1, "last Continue wins and keeps only later F8");
    CHECK(s.starts == 0 && s.continues == 1, "latest Continue determines transport");

    memset(&s, 0, sizeof s);
    for (int i = 0; i < 5; i++) seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFA);
    s.ext_pending = 1; /* clock ownership change can clear an older queue */
    apply_transport(&s);
    CHECK(s.ext_pending == 0, "queued-tick subtraction must not underflow");

    memset(&s, 0, sizeof s);
    s.clk_src = SEQ_CLK_INT;
    seq_midi_rt(&s, 0xFA);
    CHECK(s.req_start == 0, "INTERNAL ignores MIDI Start");
    seq_start(&s); apply_transport(&s);
    CHECK(s.starts == 1 && s.start_local, "INTERNAL still accepts local PLAY");
    CHECK(seq_midi_rt(&s, 0x80) == 0, "Note Off is not intercepted by MIDI realtime handler");


    /* Boundary: most recent Start supersedes a queued Continue and owns its ticks. */
    memset(&s, 0, sizeof s);
    seq_midi_rt(&s, 0xFA);
    for (int i = 0; i < 3; i++) seq_midi_rt(&s, 0xF8);
    seq_midi_rt(&s, 0xFB);
    seq_midi_rt(&s, 0xF8);
    seq_start(&s);
    seq_midi_rt(&s, 0xF8); seq_midi_rt(&s, 0xF8);
    apply_transport(&s);
    CHECK(s.ext_pending == 2, "last local Start retains only its two following clocks");
    CHECK(s.starts == 1 && s.continues == 0, "last Start supersedes remote Continue");
    CHECK(s.start_local == 1, "last local Start keeps local origin after two remote requests");

    /* Stop cancels pending remote Start, but a later local Continue survives Stop. */
    memset(&s, 0, sizeof s);
    seq_midi_rt(&s, 0xFA);
    seq_midi_rt(&s, 0xF8);
    seq_stop(&s);
    seq_midi_rt(&s, 0xF8);
    seq_continue(&s);
    seq_midi_rt(&s, 0xF8);
    apply_transport(&s);
    CHECK(s.ext_pending == 1, "Stop/local Continue discards older epoch clocks");
    CHECK(s.starts == 0 && s.continues == 1, "Stop/local Continue executes only Continue");
    CHECK(s.start_local == 1, "Stop/local Continue is not misclassified as remote");

    /* MIDI Note Off is never consumed by the realtime clock/transport dispatcher. */
    memset(&s, 0, sizeof s);
    seq_midi_rt(&s, 0xFA);
    seq_midi_rt(&s, 0xF8);
    uint32_t before = s.ext_pending;
    CHECK(seq_midi_rt(&s, 0x80) == 0, "Note Off remains available to MIDI note routing");
    CHECK(s.ext_pending == before && s.req_start == 1,
          "Note Off leaves queued Start and clock phase unchanged");

    printf("%u/%u clock epoch native checks passed\n", checks - failures, checks);
    return failures ? 1 : 0;
}
'''


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", required=True, type=pathlib.Path)
    parser.add_argument("--cc", default=os.environ.get("CC", "cc"))
    parser.add_argument("--flags", default="")
    args = parser.parse_args()
    src = args.source.read_text(encoding="utf-8")
    code = PREFIX + "\n\n".join(function_body(src, n) for n in FUNCTIONS)
    code += "\n" + SUFFIX.replace("TRANSPORT_APPLY", apply_block(src))
    with tempfile.TemporaryDirectory(prefix="x0x-clock-epoch-") as tmp:
        test_src = pathlib.Path(tmp, "clock_epoch.c")
        test_bin = pathlib.Path(tmp, "clock_epoch")
        test_src.write_text(code, encoding="utf-8")
        command = [args.cc, "-std=c11", "-Wall", "-Wextra", "-Werror", "-O1"]
        command += args.flags.split() + [str(test_src), "-o", str(test_bin)]
        print("COMPILE", " ".join(command), flush=True)
        compiled = subprocess.run(command, check=False)
        print("COMPILE_EXIT", compiled.returncode, flush=True)
        if compiled.returncode:
            return compiled.returncode
        ran = subprocess.run([str(test_bin)], check=False)
        print("TEST_EXIT", ran.returncode, flush=True)
        return ran.returncode


if __name__ == "__main__":
    sys.exit(main())

/* SPDX-License-Identifier: GPL-3.0-only */
/* Accepted SOUND layout: real production input/render/history, not a mock UI. */
#define CHICAGO_PRESENTATION_NO_MAIN
#include "chicago_presentation_test.c"
static const char *out;
static void flatten(char *to,const char *from)
{
    while(*from) {char c=*from++;if(c!=' ')*to++=c>='a' && c<='z'?(char)(c-32):c;}
    *to=0;
}
static void name_bounds(void)
{
    for(int tall=0;tall<2;tall++)for(int bank=0;bank<2;bank++)
        for(int i=0;i<factory_bank(bank)->npresets;i++) {
            preset_text_t text;char actual[64],expected[64],joined[64];
            const char *name=factory_preset_name(bank,i);preset_text(&text,name,tall);
            CHECK(text.lines>=1 && text.lines<=2);
            for(int line=0;line<text.lines;line++)CHECK(tw(text.font,text.line[line])<=54);
            put_s(put_s(joined,text.line[0]),text.line[1]);flatten(actual,joined);flatten(expected,name);
            CHECK(!strcmp(actual,expected)); /* all 111 factory names are complete, not clipped */
            CHECK(!strstr(joined,".."));
            if(!tall && text.lines==2)CHECK(text.font==&FONT_T);
        }
    preset_text_t text;
    preset_text(&text,"Acid Lab 1",1);
    CHECK(text.font==&FONT_B && text.lines==2);
    CHECK(!strcmp(text.line[0],"ACID") && !strcmp(text.line[1],"LAB 1"));
    preset_text(&text,"WWWWWWWWWWWWWWWWWWWWWWW",1);
    CHECK(text.lines==2 && strstr(text.line[1],".."));
    CHECK(tw(text.font,text.line[0])<=54 && tw(text.font,text.line[1])<=54);
    preset_text(&text,NULL,1);CHECK(!strcmp(text.line[0],"UNKNOWN"));
    preset_text(&text,"",0);CHECK(!strcmp(text.line[0],"UNKNOWN"));
}
static void acid_pixels(int selected)
{
    fixture(0,0);*page_of(V_PART)=selected?6:5;
    sound_t before=proj.sound;unsigned writes=store_writes;
    shot(out,selected?"accepted-chicago-sound":"unselected-preset-name");
    CHECK(!memcmp(&before,&proj.sound,sizeof before) && store_writes==writes);
    /* Independently prescribed approved two-line name at native 240 px. */
    uint16_t bg=selected?RGB(37,59,45):RGB(16,26,31),ink=selected?RGB(224,235,214):RGB(222,231,223);
    cv_begin(240,66,bg);text_c(92,28,&FONT_B,"ACID",ink);text_c(92,44,&FONT_B,"LAB 1",ink);
    for(int y=27;y<61;y++)for(int x=65;x<119;x++)CHECK(fb[(158+y)*240+x]==cv_px[y*240+x]);
    CHECK(fb[170*240+181]==swap16(bg)); /* right-half STATUS has no fourth-cell divider */
}
static void physical_and_history(int voice)
{
    fixture(voice,0);*page_of(V_PART)=5;
    CHECK(UI_FIRST_KNOB+3==8); /* panel.c's physical K8 is logical EN_K4 */
    CHECK(pg.r[5][3].kind==R_ENG && pg.r[5][3].c==CHI_DAMPER && pg.r[5][3].b==voice);
    CHECK(pg.r[5][1].c==CHI_FX_EDIT1); /* old K6 no longer owns DAMPER */
    pref_set(pg.r[5][3],63);pref_set(pg.r[5][1],20);audio();
    now_ms+=1000;enc_acc[EN_K2]=1;ui_input_only();
    CHECK(pref_get(pg.r[5][1])==21 && pref_get(pg.r[5][3])==63);
    undo_start();sound_t before=proj.sound;
    now_ms+=1000;enc_acc[EN_K4]=1;ui_input_only();audio();sound_t after=proj.sound;
    CHECK(pref_get(pg.r[5][3])==64 && pref_get(pg.r[5][1])==21);
    CHECK(!memcmp(before.v[T_303][voice^1],after.v[T_303][voice^1],NPARAMS_MAX));
    for(int i=0;i<engine_nparams(T_303,voice);i++)if(i!=CHI_DAMPER)
        CHECK(before.v[T_303][voice][i]==after.v[T_303][voice][i]);
    do_undo(0);CHECK(!undo_wait && !memcmp(&before,&proj.sound,sizeof before));
    do_undo(1);CHECK(!undo_wait && !memcmp(&after,&proj.sound,sizeof after));
    *page_of(V_PART)=6;int page=cur_page(),dirty=ui.dirty;unsigned writes=store_writes;
    for(int k=2;k<4;k++) {now_ms+=1000;enc_acc[EN_K1+k]=1;ui_input_only();}
    CHECK(!memcmp(&after,&proj.sound,sizeof after) && page==cur_page() && dirty==ui.dirty && writes==store_writes);
