static void test_factory_decode(void)
{
    uint8_t out[4];
    {
        const uint8_t init[4] = {0, 128, 0, 213};
        chi_arp_decode_factory(init, out);
        CHECK(out[0] == CHI_ARP_OFF && out[1] == CHI_ARP_UP && out[2] == CHI_ARP_OCT1 &&
                  out[3] == CHI_ARP_SPD_1_16,
