static void tick(uint32_t n) { while (n--) run_ms(1); }
static void btn(int b, int down)
{
    if (down) held_btn |= 1u << b;
    else held_btn &= ~(1u << b);
    tick(1);
}
static void key(int k, int down)
{
    if (down) held_keys |= 1u << k;
    else held_keys &= ~(1u << k);
    tick(1);
